import sys, json, time
from appium import webdriver
from appium.options.ios import XCUITestOptions

UDID = "3A7F396C-CC83-474D-A894-959C2B255ECC"
BUNDLE = "xyz.blueskyweb.app"

opts = XCUITestOptions()
opts.udid = UDID
opts.platform_name = "iOS"
opts.automation_name = "XCUITest"
opts.no_reset = True
opts.new_command_timeout = 600
driver = webdriver.Remote("http://127.0.0.1:4723", options=opts)

def out(obj):
    print(json.dumps(obj), flush=True)

def find(pred, root=None):
    src = driver.page_source
    return src

def do(cmd):
    c = cmd.get("cmd")
    try:
        if c == "activate":
            driver.activate_app(BUNDLE)
            time.sleep(2)
            out({"ok": True})
        elif c == "source":
            out({"ok": True, "source": driver.page_source})
        elif c == "tap":
            driver.tap([(cmd["x"], cmd["y"])])
            time.sleep(cmd.get("wait", 1.5))
            out({"ok": True})
        elif c == "type":
            el = driver.switch_to.active_element
            el.send_keys(cmd["text"])
            time.sleep(1)
            out({"ok": True})
        elif c == "press":
            driver.press_keycode(cmd["key"])
            out({"ok": True})
        elif c == "screenshot":
            driver.get_screenshot_as_file(cmd["path"])
            out({"ok": True, "path": cmd["path"]})
        elif c == "size":
            out({"ok": True, "size": driver.get_window_size()})
        elif c == "quit":
            out({"ok": True})
            return False
        else:
            out({"ok": False, "err": "unknown cmd"})
    except Exception as e:
        out({"ok": False, "err": str(e)[:500]})
    return True

for line in sys.stdin:
    line = line.strip()
    if not line:
        continue
    try:
        cmd = json.loads(line)
    except Exception as e:
        out({"ok": False, "err": "bad json: %s" % e})
        continue
    if not do(cmd):
        break

driver.quit()

import sys, json, time, os
from appium import webdriver
from appium.options.ios import XCUITestOptions

UDID = "3A7F396C-CC83-474D-A894-959C2B255ECC"
BUNDLE = "xyz.blueskyweb.app"
CMD = "/tmp/bsky_cmd"
RES = "/tmp/bsky_res"

def make_driver():
    opts = XCUITestOptions()
    opts.udid = UDID
    opts.platform_name = "iOS"
    opts.automation_name = "XCUITest"
    opts.no_reset = True
    opts.new_command_timeout = 900
    return webdriver.Remote("http://127.0.0.1:4723", options=opts)

driver = None

def ensure_driver():
    global driver
    if driver is None:
        driver = make_driver()
    return driver

def run(cmd):
    d = ensure_driver()
    c = cmd.get("cmd")
    if c == "activate":
        d.activate_app(cmd.get("bundle", BUNDLE))
        time.sleep(cmd.get("wait", 2.5))
        return {"ok": True}
    if c == "tap":
        d.tap([(cmd["x"], cmd["y"])])
        time.sleep(cmd.get("wait", 2.0))
        return {"ok": True}
    if c == "type":
        d.switch_to.active_element.send_keys(cmd["text"])
        time.sleep(cmd.get("wait", 1.0))
        return {"ok": True}
    if c == "source":
        return {"ok": True, "source": d.page_source}
    if c == "screenshot":
        d.get_screenshot_as_file(cmd["path"])
        return {"ok": True, "path": cmd["path"]}
    if c == "dump":
        tag = cmd["tag"]
        with open("/tmp/src_%s.xml" % tag, "w") as f:
            f.write(d.page_source)
        d.get_screenshot_as_file("/tmp/s_%s.png" % tag)
        return {"ok": True, "tag": tag}
    if c == "sleep":
        time.sleep(cmd.get("wait", 1.0))
        return {"ok": True}
    return {"ok": False, "err": "unknown cmd %s" % c}

for f in (CMD, RES):
    if os.path.exists(f):
        os.remove(f)

while True:
    if os.path.exists(CMD):
        try:
            with open(CMD) as f:
                cmd = json.load(f)
            os.remove(CMD)
        except Exception as e:
            cmd = None
            res = {"ok": False, "err": "bad cmd file: %s" % e}
        if cmd is not None:
            if cmd.get("cmd") == "quit":
                res = {"ok": True}
            else:
                try:
                    res = run(cmd)
                except Exception as e:
                    res = {"ok": False, "err": str(e)[:800]}
                    driver = None
            res["seq"] = cmd.get("seq") if cmd else None
            tmp = RES + ".tmp"
            with open(tmp, "w") as f:
                json.dump(res, f)
            os.rename(tmp, RES)
            if cmd and cmd.get("cmd") == "quit":
                break
    time.sleep(0.3)

try:
    if driver:
        driver.quit()
except Exception:
    pass
